\begin{aligned}
v^{\prime} &=v\left[\frac{v-\left(v_{0}\right)}{v-v_{s}}\right] \\
&=v\left[\frac{v+v_{0}}{v-v_{s}}\right]=v\left[\frac{v+v_{b}}{v-v_{b}}\right]
\end{aligned}
$$
$$
\begin{aligned}
&=v\left[\frac{330+4}{330-4}\right] 90 \times 10^{3} \\
